using System.Collections.Generic;
namespace CivicPressure
{
    internal static partial class L
    {
        private static Dictionary<string, string[]> Build()
        {
            Dictionary<string, string[]> d = new Dictionary<string, string[]>();
            d.Add("경찰 도착 · 현장 진압과 저항 진행 중", new string[] { "Police arrived · Suppression and resistance in progress", "警方已到场 · 正在镇压与抵抗", "警察到着・鎮圧と抵抗が進行中", "Policía presente · Intervención y resistencia en curso" });
            d.Add("현장 진압 중 · 남은 저항 인원과 경찰 상태로 승패 결정", new string[] { "Intervention underway · Outcome depends on remaining resistance and police", "正在镇压 · 按剩余抵抗人员与警力状态判定胜负", "鎮圧中・残る抵抗者と警察の状態で勝敗を判定", "Intervención en curso · Resultado según la resistencia y los policías restantes" });
            d.Add("경찰 도착 대기 · 현장 전투로 진압 판정", new string[] { "Awaiting police · Outcome decided by the confrontation", "等待警方到场 · 由现场战斗决定结果", "警察の到着待ち・現場の戦闘で結果を判定", "Esperando a la policía · El enfrentamiento determina el resultado" });
            d.Add("경찰은 저지선을 형성하며 진압합니다. 남은 폭동대가 모두 저항을 멈추면 경찰 승리, 대응 가능한 경찰과 대기 증원이 없으면 경찰이 철수합니다. 활동 중인 폭동대의 피해는 계속될 수 있습니다.", new string[] { "Police form a line and intervene. Police win when all remaining rioters stop resisting; they withdraw when no active officers or pending reinforcements remain. Active rioters may continue causing damage.", "警方组成防线实施镇压。剩余骚乱者全部停止抵抗时警方获胜；无可行动警员及待到增援时警方撤退。仍在活动的骚乱者可能继续造成破坏。", "警察は阻止線を形成して鎮圧します。残る暴動参加者全員が抵抗をやめると警察の勝利です。対応可能な警官も待機中の増援もいなければ撤退します。活動中の暴動参加者による被害は続く場合があります。", "La policía forma una línea e interviene. Gana cuando cesa toda resistencia; se retira si no quedan agentes activos ni refuerzos pendientes. Los alborotadores activos pueden seguir causando daños." });
            d.Add("습격 전 감속 중", new string[] { "Slowing down under attack", "遇袭减速中", "襲撃により減速中", "Reduciendo velocidad bajo ataque" });
            d.Add("참가자 접근 중", new string[] { "Attackers approaching", "袭击者正在接近", "襲撃者が接近中", "Atacantes acercándose" });
            d.Add("차량 습격 · 올라타기", new string[] { "Vehicle attack · Climbing aboard", "车辆遇袭 · 正在攀爬", "車両襲撃・よじ登り中", "Ataque al vehículo · Subiendo" });
            d.Add("차량 습격 · 흔들기 (4회)", new string[] { "Vehicle attack · Rocking (4 times)", "车辆遇袭 · 摇晃（4次）", "車両襲撃・揺さぶり（4回）", "Ataque al vehículo · Balanceo (4 veces)" });
            d.Add("차량 습격 · 참가자 뛰어내리기", new string[] { "Vehicle attack · Attackers jumping off", "车辆遇袭 · 袭击者跳下", "車両襲撃・襲撃者が飛び降り中", "Ataque al vehículo · Los atacantes saltan" });
            d.Add("미끄러지는 차량 · 폭동 피해", new string[] { "Sliding vehicle · Riot damage", "滑行车辆 · 骚乱损害", "滑走中の車両・暴動被害", "Vehículo deslizándose · Daños por disturbios" });
            d.Add("미끄러지는 전복 차량 · 폭동 피해", new string[] { "Sliding overturned vehicle · Riot damage", "翻覆车辆滑行中 · 骚乱损害", "滑走中の横転車両・暴動被害", "Vehículo volcado deslizándose · Daños por disturbios" });
            d.Add("불타는 차량 · 폭동 피해", new string[] { "Burning vehicle · Riot damage", "起火车辆 · 骚乱损害", "炎上車両・暴動被害", "Vehículo en llamas · Daños por disturbios" });
            d.Add("옆으로 넘어져 불타는 차량 · 폭동 피해", new string[] { "Vehicle on its side, burning · Riot damage", "侧翻起火车辆 · 骚乱损害", "側面に横転・炎上した車両・暴動被害", "Vehículo de lado y en llamas · Daños por disturbios" });
            d.Add("불타는 전복 차량 · 폭동 피해", new string[] { "Overturned burning vehicle · Riot damage", "翻覆起火车辆 · 骚乱损害", "横転・炎上車両・暴動被害", "Vehículo volcado en llamas · Daños por disturbios" });
            d.Add("폭동 피해 차량 · 운행 불가 · 폭동 종료 후 순차 정리", new string[] { "Riot-damaged vehicle · Out of service · Cleared gradually after the riot", "骚乱受损车辆 · 无法行驶 · 骚乱结束后逐步清理", "暴動被害車両・走行不能・暴動終了後に順次撤去", "Vehículo dañado · Fuera de servicio · Retirada gradual tras los disturbios" });
            d.Add("시위·폭동의 개인별 이동과 차량 습격을 개선했습니다. 피해 차량은 승객 하차 후 화재·전복 상태로 남으며, 종료 후 순차 정리됩니다. 구급차는 습격에서 제외합니다.", new string[] { "Reworked individual protest and riot movement and vehicle attacks. After occupants leave, damaged vehicles remain burning or overturned and are cleared gradually after the event. Ambulances are excluded from attacks.", "重制示威、骚乱的个体移动及车辆袭击。乘员下车后，受损车辆以起火或翻覆状态保留，事件结束后逐步清理。救护车不受袭击。", "デモ・暴動の個別移動と車両襲撃を改善しました。乗員の降車後、被害車両は炎上・横転状態で残り、終了後に順次撤去されます。救急車は襲撃の対象外です。", "Se renovaron los movimientos individuales y ataques a vehículos. Tras bajar los ocupantes, los vehículos dañados quedan ardiendo o volcados y se retiran gradualmente al terminar. Las ambulancias están exentas." });
            d.Add("경찰 저지선·진압·후퇴·연행과 구급대 치료·증원을 추가했습니다. 승패는 현장 전투로 결정되며, 실탄 사격은 유혈 없는 사망을 일으킬 수 있습니다.", new string[] { "Added police lines, suppression, retreat, arrests, paramedic treatment and reinforcements. Outcomes follow the confrontation; live ammunition can cause deaths without blood effects.", "新增警察防线、镇压、撤退、押送、急救治疗及增援。胜负由现场战斗决定；实弹射击可能造成死亡，但没有血腥效果。", "警察の阻止線・鎮圧・撤退・連行、救急隊の治療と増援を追加しました。勝敗は現場の戦闘で決まり、実弾射撃では流血表現なしで死亡する場合があります。", "Se añadieron líneas policiales, intervención, retirada, arrestos, atención médica y refuerzos. El enfrentamiento determina el resultado; la munición real puede causar muertes sin efectos de sangre." });
            d.Add("군중·진압 효과음과 사망 표시를 추가하고, 사건 보고서에 양측 부상자·사망자 수를 기록합니다.", new string[] { "Added crowd and response sounds, death markers, and injury/death totals for both sides in incident reports.", "新增人群、镇压音效及死亡标记，并在事件报告中记录双方受伤与死亡人数。", "群衆・鎮圧の効果音と死亡表示を追加し、事件報告書に双方の負傷者・死者数を記録します。", "Se añadieron sonidos de multitud e intervención, marcadores de fallecidos y totales de heridos y muertos de ambos bandos en los informes." });
            d.Add("폭동·경찰 · 현장 대응\n\n시위는 느슨하게 행진하며 폭동대는 각자 이동·저항합니다.\n폭동은 차량 습격·화재·건물과 도로 피해를 일으킵니다.\n구급차는 습격하지 않습니다. 일반 자가용 일부는 통제 도로를 통과합니다.\n\n첫 경찰 출동은 최대 3대이며, 지원과 치료에는 실제 경찰차·구급차가 필요합니다.\n경찰은 저지선·최루탄·곤봉·고무탄으로 대응하며 일부는 실탄을 사용합니다.\n실탄은 사망을 일으킬 수 있으며 유혈은 표시하지 않습니다.\n부상 경관은 치료 후 한 사건에서 최대 2회 복귀합니다.\n\n모든 폭동대가 저항을 멈추면 경찰 승리입니다.\n대응 가능한 경관과 대기 증원이 없으면 경찰이 철수합니다.\n패배한 폭동대는 흩어져 도주하고, 승리하면 주변 차량을 습격하거나 행진을 이어갑니다.\n사망자는 해골 표시로 구분하며, 시신은 사건 종료까지 유지합니다.\n피해 차량은 사건 종료 후 순차 정리합니다.\n\n기존 도시를 별도 저장한 뒤 업데이트를 시험해 주세요.", new string[] { "Riots and police · On-scene response\n\nProtesters march loosely; rioters move and resist individually.\nRiots can damage vehicles, buildings and roads and start fires.\nAmbulances are exempt. Some private cars may cross the controlled road.\n\nInitial police deployment is up to 3 cars; reinforcement and treatment use real service vehicles.\nPolice use lines, tear gas, batons and rubber rounds; some officers use live ammunition.\nLive rounds can kill. No blood is shown.\nInjured officers may return after treatment up to twice per incident.\n\nPolice win when all rioters stop resisting.\nThey withdraw if no active officers or pending reinforcements remain.\nDefeated rioters scatter; victors attack nearby vehicles or resume marching.\nSkulls mark the dead; bodies remain until the incident ends.\nDamaged vehicles are cleared gradually afterward.\n\nKeep a separate city save before testing the update.", "骚乱与警察 · 现场应对\n\n示威者松散行进；骚乱者独立移动、抵抗。\n骚乱可袭击车辆、引发火灾并破坏建筑和道路。\n救护车不受袭击，部分私家车可通过管制道路。\n\n首次出动最多3辆警车，增援和治疗使用实际服务车辆。\n警方采用防线、催泪弹、警棍和橡皮弹，部分警员使用实弹。\n实弹可能致死，但无血腥表现。\n受伤警员接受治疗后，每起事件最多复归2次。\n\n所有骚乱者停止抵抗时警方获胜。\n无可行动警员及待到增援时警方撤退。\n落败者四散逃跑；获胜者袭击附近车辆或继续行进。\n骷髅标记死者，遗体保留到事件结束。\n受损车辆随后逐步清理。\n\n测试更新前请另存城市。", "暴動と警察・現場対応\n\nデモは緩やかに行進し、暴動参加者は個別に移動・抵抗します。\n暴動は車両襲撃・火災・建物や道路の被害を引き起こします。\n救急車は対象外です。一部の自家用車は規制道路を通過します。\n\n最初の警察出動は最大3台。増援と治療には実際の車両を使います。\n阻止線・催涙弾・警棒・ゴム弾で対応し、一部の警官は実弾を使います。\n実弾は死亡につながりますが流血表示はありません。\n負傷警官は治療後、1事件で最大2回復帰できます。\n\n全員が抵抗をやめると警察の勝利です。\n対応可能な警官も待機中の増援もいなければ撤退します。\n敗者は散って逃走し、勝者は付近の車両を襲撃するか行進を続けます。\n死者はドクロで表示され、遺体は事件終了まで残ります。\n被害車両はその後、順次撤去します。\n\n更新の試験前に都市を別名で保存してください。", "Disturbios y policía · Respuesta\n\nLos manifestantes marchan sin formación rígida; los alborotadores actúan individualmente.\nLos disturbios pueden atacar vehículos, provocar incendios y dañar edificios y carreteras.\nLas ambulancias están exentas. Algunos coches pueden cruzar la zona controlada.\n\nEl primer despliegue es de hasta 3 patrullas; los refuerzos y tratamientos usan vehículos reales.\nLa policía usa líneas, gas, porras y balas de goma; algunos agentes usan munición real.\nPuede causar muertes, sin sangre visible.\nLos heridos pueden volver tras recibir atención hasta dos veces por incidente.\n\nLa policía gana cuando cesa toda resistencia.\nSe retira si no quedan agentes activos ni refuerzos pendientes.\nLos derrotados se dispersan; los vencedores atacan vehículos cercanos o siguen marchando.\nLas calaveras señalan a los muertos; los cuerpos permanecen hasta el final.\nLos vehículos dañados se retiran gradualmente después.\n\nGuarda una copia de la ciudad antes de probar la actualización." });
            d.Add("\n사상자: 미기록", new string[] { "\nCasualties: not recorded", "\n伤亡：未记录", "\n死傷者：未記録", "\nBajas: sin registro" });
            d.Add("\n폭동대: 부상 {0}명 · 사망 {1}명\n경찰: 부상 {2}명 · 사망 {3}명", new string[] { "\nRioters: {0} injured · {1} dead\nPolice: {2} injured · {3} dead", "\n骚乱者：受伤 {0}人 · 死亡 {1}人\n警察：受伤 {2}人 · 死亡 {3}人", "\n暴動参加者：負傷 {0}人・死亡 {1}人\n警察：負傷 {2}人・死亡 {3}人", "\nManifestantes violentos: {0} heridos · {1} muertos\nPolicías: {2} heridos · {3} muertos" });
            d.Add("\n사상자 부분 기록: 불러오기 전후 참가자는 별도로 집계", new string[] { "\nPartial casualty record: participants before and after loading are counted separately", "\n伤亡部分记录：载入前后的参与者分别统计", "\n死傷者の部分記録：ロード前後の参加者は別々に集計", "\nRegistro parcial de bajas: los participantes antes y después de cargar se cuentan por separado" });
            d.Add("폭동 진압 과정에서 과도한 물리력이 사용됐습니다. 조사해 주세요.", new string[] { "Excessive force was used during the riot response. Please investigate.", "镇压骚乱时使用了过度武力，请调查。", "暴動の鎮圧で過剰な実力行使がありました。調査してください。", "Se utilizó fuerza excesiva durante la intervención. Solicito una investigación." });
            d.Add("진압 과정에 대한 민원을 접수했으며, 현장 대응 경위를 검토하겠습니다.", new string[] { "We have received the complaint and will review the circumstances of the response.", "已受理有关处置过程的投诉，将核查现场应对情况。", "鎮圧に関する陳情を受け付け、現場対応の経緯を確認します。", "Hemos recibido la queja y revisaremos las circunstancias de la intervención." });
            d.Add("건강·범죄·쓰레기·소방 위험을 정보 보기의 건물 상태값에 맞췄습니다. 불량 방향 60%부터 경고, 80%부터 심각으로 집계합니다.", new string[] { "Health, crime, garbage and fire risk now use the building values behind the info views. Complaints count from 60% toward the bad end of the scale, severe from 80%.", "健康、犯罪、垃圾和火灾风险现采用信息视图的建筑状态值。向不良端达到60%计为警告，80%计为严重。", "健康・犯罪・ごみ・火災リスクを情報ビューの建物状態値に合わせました。悪化側60%から警告、80%から深刻として集計します。", "La salud, el crimen, la basura y el riesgo de incendio usan los valores de los edificios de las vistas de información. Se cuenta como aviso desde el 60% hacia el extremo malo y como grave desde el 80%." });
            d.Add("교육 민원은 해당 교육 단계의 건물 학력 상태가 나쁘고 실제 학교 배정도 부족할 때만 집계합니다. 낮은 학력만으로 민원을 만들지 않습니다.", new string[] { "Education complaints require both poor building attainment for the relevant school stage and an actual missing school assignment. Low attainment alone creates no complaint.", "教育投诉须同时满足对应教育阶段的建筑学历状况不良和实际缺少学校分配。仅学历较低不会产生投诉。", "教育の民願には該当段階の建物の学歴状態の悪化と、実際の学校配属不足の両方が必要です。低学歴だけでは発生しません。", "Las quejas educativas requieren bajo nivel educativo del edificio en la etapa correspondiente y falta real de asignación escolar. El bajo nivel educativo por sí solo no genera quejas." });
            d.Add("건물 상태 · 민원 기준\n\n도로의 서비스 범위 대신 건물 상태의 계산값을 사용합니다.\n불량 방향 60%부터 경고, 80%부터 심각입니다.\n중간색과 양호 상태는 이번 항목의 피해로 세지 않습니다.\n\n건강: 건물 평균 건강 50 이하 / 심각 25 이하\n범죄: 건물 범죄 지표 60% 이상 / 심각 80% 이상\n쓰레기: 적체량 3,000 이상 / 심각 4,000 이상\n소방: 건물 안전 지표 40 이하 / 심각 20 이하\n실제 화재는 안전 지표와 관계없이 심각입니다.\n\n교육: 해당 단계 이수율 40% 이하이고 학교 배정도 부족할 때.\n이수율 20% 이하는 심각이며, 유효한 재학생은 제외합니다.\n의료·치안 서비스 부족은 불량 건물 상태도 함께 요구합니다.\n미해금 서비스 부족은 제외하고, 구별 피해를 집계합니다.\n\n60%·80%는 모드의 기준이며 게임의 공식 경고선은 아닙니다.\n테마·모드에 따라 실제 색조는 다를 수 있습니다.\n건설 후 상태 갱신과 다음 집계까지 기다려 주세요.", new string[] { "Building state · Complaint criteria\n\nUses values behind building colors, not road coverage.\nWarning: 60% toward bad; severe: 80%.\nIntermediate and good states are not counted as harm here.\n\nHealth: household average 50 or below; severe 25 or below.\nCrime: building crime indicator 60%+; severe 80%+.\nGarbage: backlog 3,000+; severe 4,000+.\nFire: building safety 40 or below; severe 20 or below.\nActive fires are always severe regardless of safety.\n\nEducation: stage attainment 40% or less AND missing school assignment.\n20% or less is severe. Students with a valid school are excluded.\nMedical/police shortages also require a poor building state.\nLocked service shortages are excluded; harm is counted by district.\n\n60%/80% are mod thresholds, not official game warning limits.\nThemes and mods may change the actual hues.\nAfter construction, wait for state updates and the next census.", "建筑状态 · 投诉标准\n\n使用建筑颜色对应的状态值，而非道路服务范围。\n向不良端达到60%为警告，80%为严重。\n中间色和良好状态不计入这些项目的受影响人数。\n\n健康：建筑平均健康50以下；严重25以下。\n犯罪：建筑犯罪指标60%以上；严重80%以上。\n垃圾：积存3,000以上；严重4,000以上。\n消防：建筑安全指标40以下；严重20以下。\n实际火灾无论安全指标如何均为严重。\n\n教育：对应阶段学历达标率40%以下且缺少学校分配。\n20%以下为严重；已有效分配学校的学生不计入。\n医疗、治安服务不足还须建筑状态不良。\n排除未解锁服务的不足；按区统计受影响人数。\n\n60%和80%是模组标准，不是游戏官方警告线。\n主题与模组可能改变实际色调。\n建设后请等待状态更新和下一次统计。", "建物状態 · 民願の基準\n\n道路のサービス範囲ではなく建物の色の元となる値を使用します。\n悪化側60%で警告、80%で深刻です。\n中間色と良好な状態は今回の項目の被害に数えません。\n\n健康：建物の平均健康50以下、深刻25以下。\n犯罪：建物の犯罪指標60%以上、深刻80%以上。\nごみ：滞留量3,000以上、深刻4,000以上。\n消防：建物の安全指標40以下、深刻20以下。\n実際の火災は安全指標にかかわらず深刻です。\n\n教育：該当段階の修了率40%以下かつ学校配属不足。\n20%以下は深刻。有効な学校がある学生は除外します。\n医療・警察のサービス不足には建物状態の悪化も必要です。\n未解放サービスの不足を除き、地区ごとに集計します。\n\n60%・80%はモッドの基準で、ゲーム公式の警告線ではありません。\nテーマやモッドで実際の色合いは変わる場合があります。\n建設後は状態更新と次の集計をお待ちください。", "Estado del edificio · Criterios de quejas\n\nUsa los valores de los colores de edificios, no la cobertura vial.\nAviso al 60% hacia el extremo malo; grave al 80%.\nLos estados intermedios y buenos no cuentan como afectados aquí.\n\nSalud: media del edificio 50 o menos; grave 25 o menos.\nCrimen: indicador del edificio 60%+; grave 80%+.\nBasura: acumulación 3.000+; grave 4.000+.\nIncendios: seguridad del edificio 40 o menos; grave 20 o menos.\nUn incendio activo siempre es grave, sin importar la seguridad.\n\nEducación: nivel de la etapa 40% o menos Y sin asignación escolar.\n20% o menos es grave; se excluyen alumnos con escuela válida.\nLa falta de sanidad/policía también requiere un edificio en mal estado.\nSe excluyen servicios bloqueados; los afectados se cuentan por distrito.\n\n60%/80% son umbrales del mod, no avisos oficiales del juego.\nLos temas y mods pueden cambiar los tonos reales.\nTras construir, espera la actualización y el siguiente recuento." });
            d.Add("\n건물 상태 판정: 불량 방향 60%부터 경고, 80%부터 심각입니다. 실제 화재는 항상 심각입니다.", new string[] { "\nBuilding state: warning from 60% toward bad, severe from 80%. Active fires are always severe.", "\n建筑状态：向不良端60%起为警告，80%起为严重。实际火灾始终为严重。", "\n建物状態：悪化側60%から警告、80%から深刻。実際の火災は常に深刻です。", "\nEstado del edificio: aviso desde el 60% hacia malo; grave desde el 80%. Un incendio activo siempre es grave." });
            d.Add("해당 교육 단계 이수율 40% 이하와 학교 배정 부족을 함께 확인 · 20% 이하는 심각", new string[] { "Requires stage attainment at or below 40% and a missing school assignment; at or below 20% is severe.", "同时要求对应阶段学历达标率40%以下和学校分配不足；20%以下为严重。", "該当段階の修了率40%以下と学校配属不足の両方が必要。20%以下は深刻。", "Requiere nivel de la etapa del 40% o menos y falta de asignación escolar; 20% o menos es grave." });
            d.Add("의료 서비스 범위 부족·불량 건물 건강·시민 건강 문제를 함께 확인", new string[] { "Requires missing medical coverage, poor household health and a citizen health problem.", "同时要求医疗服务覆盖不足、建筑健康状态不良和市民健康问题。", "医療範囲不足・建物の健康悪化・市民の健康問題のすべてが必要。", "Requiere falta de cobertura sanitaria, mala salud del edificio y un problema de salud del ciudadano." });
            d.Add("치안 서비스 범위 부족과 건물 범죄 지표 60% 이상을 함께 확인 · 80% 이상은 심각", new string[] { "Requires missing police coverage and a building crime indicator of at least 60%; 80%+ is severe.", "同时要求治安服务覆盖不足和建筑犯罪指标60%以上；80%以上为严重。", "警察範囲不足と建物犯罪指標60%以上の両方が必要。80%以上は深刻。", "Requiere falta de cobertura policial e indicador de crimen del edificio del 60% o más; 80%+ es grave." });
            d.Add("버튼 위치 초기화", new string[] { "Reset button position", "重置按钮位置", "ボタン位置をリセット", "Restablecer posición del botón" });
            d.Add("손잡이를 끌어 버튼 위치 이동", new string[] { "Drag the grip to move the button", "拖动把手移动按钮", "ハンドルをドラッグしてボタンを移動", "Arrastra el tirador para mover el botón" });
            d.Add("Unified UI가 없을 때 메인 버튼을 왼쪽 위에 표시합니다. 옆 손잡이로 이동하면 위치를 기억하며, 옵션에서 초기화할 수 있습니다.", new string[] { "Without Unified UI, the main button appears at the upper left. Move it using the adjacent grip; its position is remembered and can be reset in options.", "未使用 Unified UI 时，主按钮显示在左上方。可用旁边的把手移动，位置会被保存，也可在选项中重置。", "Unified UI がない場合、メインボタンを左上に表示します。横のハンドルで移動すると位置を保存し、オプションでリセットできます。", "Sin Unified UI, el botón principal aparece arriba a la izquierda. Muévelo con el tirador lateral; su posición se guarda y puede restablecerse en las opciones." });
            d.Add("의료·치안·소방 평가에 사용하는 기준을 도움말에 설명했습니다. 실제 이동 거리나 출동 시간은 점수에 포함하지 않습니다.", new string[] { "Help now explains the healthcare, police and fire assessment criteria. Actual travel distances and response times are not included in the score.", "帮助中说明了医疗、治安和消防的评估标准。实际移动距离和出动时间不计入评分。", "医療・治安・消防の評価基準をヘルプで説明しました。実際の移動距離や出動時間は得点に含みません。", "La ayuda explica los criterios de evaluación sanitaria, policial y de bomberos. La distancia real de viaje y los tiempos de respuesta no se incluyen en la puntuación." });
            d.Add("의료 서비스 민원은 게임 서비스 범위 부족과 시민 건강 문제가 함께 있을 때만 접수되며, 민원 상세에 판정 기준을 표시합니다.", new string[] { "Medical service complaints now require both missing game service coverage and affected citizens with health problems; the complaint details show these criteria.", "医疗服务投诉仅在游戏服务覆盖不足且受影响市民存在健康问题时受理；投诉详情会显示这些判定标准。", "医療サービスの民願は、ゲーム内のサービス範囲が不足し、影響を受けた市民に健康上の問題がある場合にのみ受理されます。民願の詳細にはこの判定基準を表示します。", "Las quejas por servicio sanitario solo se reciben cuando falta cobertura del juego y los ciudadanos afectados tienen problemas de salud; los detalles muestran estos criterios." });
            d.Add("도시 진행에서 아직 해금하지 않은 의료·치안·소방 서비스는 부족 민원과 감점에서 제외합니다.", new string[] { "Healthcare, police and fire services that are not yet unlocked by city progression are excluded from shortage complaints and penalties.", "城市发展中尚未解锁的医疗、治安和消防服务不会产生短缺投诉或扣分。", "都市の進行でまだアンロックされていない医療・警察・消防サービスは、不足の民願と減点の対象外です。", "Los servicios sanitarios, policiales y de bomberos aún no desbloqueados por el progreso de la ciudad se excluyen de las quejas y penalizaciones por falta de servicio." });
            d.Add("\n의료 민원 판정: 게임 의료 서비스 범위 부족과 건강 문제가 함께 확인되었습니다.", new string[] { "\nMedical complaint: the game's medical service coverage is insufficient and affected citizens have health problems.", "\n医疗投诉判定：游戏医疗服务覆盖不足，且受影响市民存在健康问题。", "\n医療の民願判定：ゲーム内の医療サービス範囲が不足し、影響を受けた市民に健康上の問題があります。", "\nQueja médica: la cobertura sanitaria del juego es insuficiente y los ciudadanos afectados tienen problemas de salud." });
            d.Add("의료·치안·소방 · 평가 기준\n\n의료·치안·소방 서비스는 주거 건물 위치의 게임 서비스 범위를 확인합니다.\n건강 악화와 범죄는 시민 상태·건물 경고를, 화재는 건물의 화재 상태를 함께 집계합니다.\n시설 수나 지도의 색만으로 모든 불만이 사라지지는 않습니다.\n\n실제 병원까지의 이동 거리, 경찰·소방 차량의 출동 시간과 도착 지연은 점수에 직접 반영하지 않습니다.\n서비스 범위와 실제 이동·출동 경험은 서로 다를 수 있습니다.\n\n시설을 개선한 뒤 게임의 상태 갱신과 다음 집계를 기다려 주세요.", new string[] {
                "Healthcare, police and fire · Assessment criteria\n\nHealthcare, police and fire services are assessed using the game's service coverage at residential buildings.\nPoor health and crime also use citizen states and building warnings; fires use the building's fire state.\nFacility counts or map colors alone do not clear every complaint.\n\nActual travel distance to hospitals, police/fire response times and arrival delays are not directly included in the score.\nService coverage can differ from actual travel and response experiences.\n\nAfter improving facilities, allow the game to update its state and wait for the next census.",
                "医疗、治安、消防 · 评估标准\n\n医疗、治安和消防服务按住宅建筑位置的游戏服务覆盖范围评估。\n健康恶化与犯罪还会统计市民状态和建筑警告；火灾会统计建筑的火灾状态。\n设施数量或地图颜色并不能消除所有投诉。\n\n到医院的实际移动距离、警车和消防车的出动时间及到达延迟不直接计入评分。\n服务覆盖范围可能与实际出行和出动体验不同。\n\n改善设施后，请等待游戏状态更新和下一次统计。",
                "医療・治安・消防 · 評価基準\n\n医療・治安・消防サービスは住宅の位置におけるゲームのサービス範囲を確認します。\n健康悪化と犯罪は市民の状態・建物の警告を、火災は建物の火災状態も集計します。\n施設数やマップの色だけではすべての不満は解消しません。\n\n病院への実際の移動距離、警察・消防車の出動時間や到着遅延は得点に直接反映しません。\nサービス範囲と実際の移動・出動状況は異なる場合があります。\n\n施設を改善したら、ゲームの状態更新と次の集計をお待ちください。",
                "Sanidad, policía y bomberos · Criterios de evaluación\n\nEstos servicios se evalúan según la cobertura del juego en los edificios residenciales.\nLa mala salud y el crimen también usan estados de ciudadanos y avisos de edificios; los incendios usan el estado de fuego del edificio.\nEl número de instalaciones o los colores del mapa no eliminan todas las quejas.\n\nLa distancia real al hospital, los tiempos de respuesta policial y de bomberos y los retrasos de llegada no se incluyen directamente en la puntuación.\nLa cobertura puede diferir de la experiencia real de viaje y respuesta.\n\nTras mejorar las instalaciones, espera a que el juego actualice su estado y al siguiente recuento." });
            d.Add("켜짐", new string[] { "On", "开启", "オン", "Activado" });
            d.Add("꺼짐", new string[] { "Off", "关闭", "オフ", "Desactivado" });
            d.Add("도구", new string[] { "Tools", "工具", "ツール", "Herramientas" });
            d.Add("방문자 표시 유지", new string[] { "Remember visitor markers", "记住来访者标记显示状态", "来訪者の表示状態を保存", "Recordar marcadores de visitantes" });
            d.Add("민원 지도 표시 유지", new string[] { "Remember complaint map", "记住民诉地图显示状态", "民願マップの表示状態を保存", "Recordar mapa de quejas" });
            d.Add("평가·방문자·지도·기록 버튼을 도시 행정 창의 도구 메뉴로 묶었습니다. 방문자·민원 지도 표시 상태는 다시 시작해도 유지됩니다. 옵션에서 난이도 고급 설정을 켜면 행복도 감점, 사건 빈도, 민원 대응 기한 같은 값을 직접 조절할 수 있습니다.", new string[] { "Review, Visitors, Map and Records now sit in the administration window's Tools menu. Visitor and complaint-map visibility persist across restarts. Advanced difficulty options still let you tune penalties, event frequency and response deadlines.", "评价、来访者、地图和记录现集中在城市行政窗口的工具菜单中。来访者和民诉地图的显示状态在重启后保持。高级难度选项仍可调整惩罚、事件频率及回应期限。", "評価・来訪者・地図・記録を都市行政ウィンドウのツールメニューにまとめました。来訪者と民願マップの表示状態は再起動後も維持されます。詳細な難易度設定では減点・発生頻度・対応期限を調整できます。", "Evaluación, Visitantes, Mapa y Registros están en el menú Herramientas de la ventana de administración. La visibilidad de visitantes y del mapa se conserva al reiniciar. Las opciones avanzadas permiten ajustar penalizaciones, frecuencia y plazos." });
            d.Add("고용 민원의 접수·종결 기준과 대응 시간을 완화했습니다. 실제 피해가 줄면 행복도 감점도 줄고, 접수 당시보다 피해율이 20% 감소하면 한 번 더 대응 시간을 줍니다. 시설 반대·주민 건의를 끌 때 남던 처리와 행정 평가 창의 정렬 오류를 수정했습니다. 저장된 시간 배율을 이용해 Real Time 변경 시 진행 중인 기한을 유지합니다.", new string[] { "Labor complaints have more forgiving thresholds and deadlines. Happiness penalties shrink with real harm, and a 20% reduction from intake grants extra response time once. Fixed lingering processing after disabling facility opposition or resident suggestions, and review-window alignment. Saved clock scales preserve active timer hours when switching Real Time.", "放宽了就业类投诉的受理、结案门槛和回应时间。实际影响减少时幸福度扣分也会下降，比受理时降低20%可额外获得一次回应时间。修复关闭设施反对或居民建议后仍继续处理的问题，以及行政评估窗口对齐错误。保存时间倍率，以便切换Real Time时保留进行中计时。", "雇用関連の受付・終了基準と対応期限を緩和しました。実際の被害が減ると幸福度減点も減り、受付時より被害率が20%減れば一度だけ対応時間を追加します。施設反対・住民提案を無効にしても処理が残る問題と行政評価画面の配置を修正しました。時間倍率を保存し、Real Timeの切り替え時に進行中の残り時間を維持します。", "Las quejas laborales tienen umbrales y plazos más flexibles. La penalización de felicidad baja con el daño real y una reducción del 20% desde la apertura concede tiempo adicional una sola vez. Se corrigieron los procesos que seguían tras desactivar la oposición a instalaciones o las sugerencias, y la alineación de la evaluación. La escala guardada conserva los plazos activos al cambiar Real Time." });
            d.Add("\n고용 피해율 20% 감소 확인 · 추가 대응 시간 지급 완료", new string[] { "\nLabor impact down 20% · extra response time granted", "\n就业影响率下降20% · 已给予额外回应时间", "\n雇用被害率20%減を確認 · 対応時間を追加済み", "\nImpacto laboral reducido un 20% · prórroga concedida" });
