            d.Add("도로가 교체되어 행진을 중단했습니다. 현재 위치의 교통 통제와 해산 조건은 유지됩니다.", new string[] { "Road replaced; march paused. Local traffic control and dispersal conditions still apply.", "道路已更换，游行暂停。现场交通管制和解散条件仍有效。", "道路変更で行進を停止しました。現場の交通規制と解散条件は維持されます。", "Vía sustituida; marcha detenida. Se mantienen el corte local y las condiciones de dispersión." });
            d.Add("도시 운영 난이도 · 1 여유 / 3 기준 / 5 극한", new string[] { "City difficulty · 1 Relaxed / 3 Standard / 5 Extreme", "城市难度 · 1宽松 / 3标准 / 5极限", "都市運営難易度・1ゆったり / 3標準 / 5極限", "Dificultad · 1 Relajado / 3 Normal / 5 Extremo" });
            d.Add("도시 전체 집계", new string[] { "All-city survey", "全市统计", "都市全体の集計", "Recuento de toda la ciudad" });
