            d.Add("방문자가 이미 도착했거나 이동을 멈췄습니다.", new string[] { "The visitor has already arrived or stopped travelling.", "来访者已到达或已停止前往。", "来庁者はすでに到着したか、移動をやめました。", "El visitante ya llegó o dejó de desplazarse." });
            d.Add("Unified UI 모드를 쓰면 행정 창 버튼이 Unified UI 툴바에 들어갑니다.", new string[] { "With the Unified UI mod, the administration button moves into the Unified UI toolbar.", "使用 Unified UI 模组时，行政窗口按钮会放入 Unified UI 工具栏。", "Unified UI MODを使うと、行政ウィンドウのボタンがUnified UIツールバーに入ります。", "Con el mod Unified UI, el botón de administración pasa a la barra de Unified UI." });
            d.Add("번역 파일로 새 언어를 추가할 수 있습니다. 옵션의 언어 탭에 표시된 폴더에 언어 파일을 넣으면 목록에 나타나며, 번역되지 않은 문장은 영어로 표시됩니다.", new string[] { "New languages can be added with translation files. Put a language file in the folder shown on the options' Language tab and it appears in the list; untranslated texts are shown in English.", "现在可以通过翻译文件添加新语言。将语言文件放入选项“语言”页显示的文件夹后即会出现在列表中，未翻译的文本以英文显示。", "翻訳ファイルで新しい言語を追加できます。オプションの言語タブに表示されるフォルダーに言語ファイルを入れると一覧に表示され、未翻訳の文章は英語で表示されます。", "Ahora se pueden añadir idiomas con archivos de traducción. Coloca un archivo en la carpeta indicada en la pestaña Idioma de las opciones y aparecerá en la lista; los textos sin traducir se muestran en inglés." });
            d.Add("Real Time 2.8 모드가 없어도 모드는 진행되지만, 원활한 진행을 위해 Real Time 모드(창작마당 3059406297) 설치를 권장합니다.", new string[] { "Civic Pressure works without the Real Time 2.8 mod, but installing Real Time (Workshop 3059406297) is recommended for smoother play.", "没有 Real Time 2.8 模组也能运行本模组，但为了更顺畅的体验，建议安装 Real Time 模组（创意工坊 3059406297）。", "Real Time 2.8 MODがなくても本MODは動作しますが、快適に遊ぶためにReal Time MOD（ワークショップ 3059406297）の導入をおすすめします。", "Civic Pressure funciona sin el mod Real Time 2.8, pero se recomienda instalar Real Time (Workshop 3059406297) para una partida más fluida." });
