            d.Add("수동 발생 지역: ", new string[] { "Manual origin: ", "手动发生地区：", "手動発生地域：", "Origen manual: " });
            d.Add("수동 발생: 담당 행정청으로 이어지는 행진 경로 탐색 중…", new string[] { "Manual spawn: finding a march route to the responsible office…", "手动发生：搜索通往负责部门的游行路线…", "手動発生：担当行政庁への行進経路を検索中…", "Generación manual: buscando ruta a la oficina…" });
            d.Add("수동 발생", new string[] { "Manual spawn", "手动发生", "手動発生", "Generación manual" });
            d.Add("수동 발생은 행복도와 자동 발생 빈도를 무시합니다. 폭동은 실제 건물과 도로에 피해를 줍니다.", new string[] { "Manual events ignore happiness and frequency settings. Riots damage actual buildings and roads.", "手动事件忽略幸福度和频率设置，暴动会损坏实际建筑和道路。", "手動発生は幸福度と頻度設定を無視します。暴動は実際の建物・道路を損傷します。", "Los eventos manuales ignoran felicidad y frecuencia. Los disturbios dañan edificios y vías reales." });
            d.Add("수동 사건은 48 게임 시간 경과가 필요합니다.", new string[] { "Manual events require 48 game hours.", "手动事件需要经过48游戏小时。", "手動事件は48ゲーム時間の経過が必要です。", "Los eventos manuales requieren 48 horas de juego." });
            d.Add("수동 시위는 문제 개선과 별도로 시간 조건을 적용합니다.", new string[] { "Manual protests use a time condition even if issues improve.", "手动示威即使问题改善仍需满足时间条件。", "手動デモは改善とは別に時間条件を適用します。", "Las protestas manuales exigen tiempo aunque mejoren los problemas." });
            d.Add("수동 폭동 전환 · 경찰 도착 후 진압하면 해산합니다.", new string[] { "Manual riot conversion · Dispersal follows police intervention.", "手动转为暴动 · 警方到场镇压后解散。", "手動で暴動へ移行・警察到着後の鎮圧で解散します。", "Conversión manual · Se disuelve tras la intervención policial." });
            d.Add("수락 · 개선 약속", new string[] { "Accept · Promise improvement", "接受 · 承诺改善", "受諾・改善を約束", "Aceptar · Mejorar" });
            d.Add("수락 · 검토 접수", new string[] { "Accept · Review", "接受 · 审核", "受諾・審査受付", "Aceptar · Revisar" });
            d.Add("수락·거절 · 개선 확인과 종결\n\n‘수락’은 개선 약속입니다. 시설을 자동으로 설치하거나\n문제를 없애 주지 않습니다. 기한 전에 수락하면 기본 대응\n기한의 절반만큼 한 차례 연장됩니다. 재발 시 더 짧아집니다.\n\n거절하면 해당 민원의 처리가 끝납니다. 실제 피해와 행복도 감점은\n남으며, 문제가 지속되면 유예 후 다시 접수될 수 있습니다.\n약속한 민원은 중복 수락·거절할 수 없습니다.\n\n일반 민원은 피해가 0명이면 종결됩니다.\n소수 피해가 남아도 종결 기준 이하를 3게임 시간 유지하면\n‘개선 확인 후 종결’됩니다. 확인 중에는 시위 확대와\n기한 불이익을 멈춥니다. 다시 악화되면 확인 시간이 초기화됩니다.\n\n일자리·교육·인력·고객 부족은 변화가 느려 접수도 늦게 합니다.\n민원 종료와 행복도 100점 회복은 같은 뜻이 아닙니다.\n잔여 피해, 다른 불만, 버려진 건물의 감점을 함께 확인하세요.", new string[] { "Accepting, declining and confirming recovery\n\nAccepting promises improvement; it does not build facilities or fix anything automatically. Accepting before the deadline grants one extension of half the base response period. Recurrences shorten it.\n\nDeclining closes this complaint, but real impact and happiness penalties remain. Persistent problems can return after a grace period. A promised complaint cannot be accepted or declined again.\n\nZero affected residents closes a normal complaint. Otherwise, staying at or below its recovery threshold for 3 game hours closes it after confirmation. Escalation and deadline penalties pause during confirmation. Worsening resets the timer.\n\nEmployment, education, staffing and customers receive longer intake waits. Closing a complaint does not mean happiness returns to 100. Check remaining impacts, other issues and abandoned buildings.", "接受、拒绝与改善确认\n\n接受表示承诺改善，不会自动建设或消除问题。期限前接受可一次延长基础应对期的一半，复发时会缩短。\n\n拒绝结束本次处理，但实际影响和幸福度扣分仍保留，持续问题可在宽限后再次受理。已承诺的投诉不能重复接受或拒绝。\n\n一般投诉受影响人数为0时结案。少量影响仍在时，保持不高于恢复阈值3游戏小时可确认结案。确认期间暂停示威升级和期限惩罚；再次恶化会重置计时。\n\n就业、教育、人员和顾客不足因变化较慢，受理等待更长。结案不等于幸福度回到100，仍须检查残余影响、其他问题和废弃建筑。", "承諾・拒否・改善確認\n\n承諾は改善の約束であり、自動建設や問題解消ではありません。期限前の承諾で基本対応期間の半分を一度だけ延長できます。再発では短くなります。\n\n拒否するとその苦情の処理は終了しますが、実際の被害と幸福度の減点は残り、継続する問題は猶予後に再受付される場合があります。約束済みの苦情は重ねて承諾・拒否できません。\n\n一般苦情は被害0人なら終了します。少数残っても終結基準以下を3ゲーム時間維持すれば改善確認後に終了します。確認中はデモ拡大と期限の不利益を止め、再悪化で確認時間をリセットします。\n\n雇用・教育・人員・顧客不足は受付まで長めです。苦情終了と幸福度100への回復は別です。残存被害や廃墟も確認してください。", "Aceptar, rechazar y confirmar mejoras\n\nAceptar promete una mejora: no construye ni soluciona nada automáticamente. Si se acepta antes del plazo, se concede una única prórroga de la mitad del período básico; las reincidencias la reducen.\n\nRechazar cierra esa queja, pero permanecen los daños y las penalizaciones. Si persiste, puede volver tras una gracia. Una queja prometida no puede aceptarse ni rechazarse otra vez.\n\nSin afectados, la queja normal se cierra. Si quedan algunos, mantener el impacto bajo el umbral de cierre durante 3 horas de juego confirma la recuperación. Durante la comprobación se pausan escaladas y sanciones por plazo. Un empeoramiento reinicia el contador.\n\nEmpleo, educación, personal y clientes esperan más antes de abrirse. Cerrar una queja no devuelve automáticamente la felicidad a 100: revise daños restantes y edificios abandonados." });
            d.Add("수락", new string[] { "Accept", "接受", "受諾", "Aceptar" });
