            d.Add("출동 차량 중 대표 차량을 따라봅니다. 다시 누르면 추적을 멈춥니다.", new string[] { "Follow a lead vehicle from the deployment. Press again to stop following.", "跟随出动队伍的代表车辆，再次点击停止跟随。", "出動中の代表車両を追跡します。再度押すと解除します。", "Sigue un vehículo del despliegue. Pulse otra vez para dejar de seguirlo." });
            d.Add("출동할 수 없습니다. 시청 지정 상태를 확인하세요.", new string[] { "Cannot deploy. Check City Hall assignment.", "无法出动，请检查市政府指定。", "出動できません。市役所の指定を確認してください。", "No se puede desplegar. Revise la asignación del ayuntamiento." });
            d.Add("치안 서비스", new string[] { "Police coverage", "治安服务", "警察サービス", "Cobertura policial" });
            d.Add("침수 피해", new string[] { "Flood damage", "洪水损害", "浸水被害", "Daños por inundación" });
            d.Add("클릭하여 민원 해결 이력 / 시위·폭동 보고서 전환", new string[] { "Switch between resolved complaints and protest / riot reports", "切换投诉解决记录与示威 / 暴乱报告", "苦情の解決履歴とデモ・暴動報告を切り替え", "Alterna entre quejas resueltas e informes de protestas / disturbios" });
            d.Add("태양의 야간 근무는 행정청 권한 밖입니다. 양해 부탁드립니다.", new string[] { "Night shifts for the sun are outside our authority. Thank you for understanding.", "安排太阳上夜班超出行政机关权限，敬请谅解。", "太陽の夜勤は行政の権限外です。ご了承ください。", "Los turnos nocturnos del sol quedan fuera de nuestras competencias." });
            d.Add("파괴 피해 없음", new string[] { "No destruction", "无损毁", "破壊被害なし", "Sin destrucción" });
            d.Add("폭동 군중 대치 · 진압 중", new string[] { "Facing riot crowd / restoring order", "与暴乱人群对峙 / 镇压中", "暴動の群衆と対峙・鎮圧中", "Frente a la multitud / intervención" });
            d.Add("폭동 군중 위치로 긴급 출동 중", new string[] { "Emergency response to riot crowd", "紧急赶往暴乱人群位置", "暴動の群衆へ緊急出動中", "Acudiendo de urgencia a los disturbios" });
            d.Add("폭동 발생", new string[] { "Start riot", "发起暴乱", "暴動を発生", "Iniciar disturbios" });
            d.Add("폭동 이후 · 피해 복구와 경로 점검\n\n폭동은 시위보다 인원이 많고 이동도 빠릅니다.\n행진 중과 현장 주변에서 건물 화재·붕괴, 도로 피해가 생길 수 있습니다.\n경찰이 도착해 현장을 유지하는 동안 행진과 추가 피해를 멈춥니다.\n\n진압 성공은 군중 해산을 의미합니다.\n불이 난 건물과 파괴된 도로가 자동으로 복구되는 것은 아닙니다.\n소방 대응, 건물 재건과 도로 연결을 따로 확인하세요.\n현재 버전은 모든 건물 재건을 경찰 진압 성공의 조건으로 요구하지 않습니다.\n\n행진 경로는 인도가 있는 지상 일반 도로가 필요합니다.\n경로를 찾지 못하면 행정청 진입 도로와 연결 상태를 확인하세요.\n교량·고가·터널·고속도로·보행자 구역만으로 연결된 배치는\n행진 경로를 구성하지 못할 수 있습니다.\n\n경찰차 보기와 현장 보기로 위치를 각각 확인하세요.\n출동 요청 자체가 경찰 도착은 아니며, 길이 막혀 있으면 지연됩니다.\n현재 상태·실패 안내·남은 진압 시간을 시위·폭동 화면에서 확인하세요.", new string[] { "After a riot: repairs and routes\n\nRiot crowds are larger and faster than protests. Nearby buildings may burn or collapse and roads may be damaged along the march. Once police arrive and hold the scene, marching and further damage pause.\n\nSuccessful intervention disperses the crowd; it does not repair damage. Check firefighting, rebuilding and road connections separately. This version does not require every damaged building to be rebuilt for police success.\n\nMarching requires connected ground-level ordinary roads with sidewalks. Check the civic building's entrance road if no route is found. Bridges, elevated roads, tunnels, highways or pedestrian zones alone may not form a usable route.\n\nView police and View scene show separate locations. Requesting deployment is not arrival; congestion can delay it. Check status, failure messages and remaining intervention time.", "暴乱后的修复与路线\n\n暴乱人数更多、移动更快，可沿途和现场烧毁、摧毁建筑及道路。警察到场维持现场后暂停行进和新增损毁。\n\n镇压成功只代表人群解散，不会自动修复。需另行检查消防、重建和道路连接。本版本不要求重建全部建筑后才能成功镇压。\n\n行进需要带人行道的地面普通道路。找不到路线时检查行政建筑入口及连接，只有桥梁、高架、隧道、高速或步行区可能无法形成路线。\n\n警车与现场按钮分别显示位置。请求出动不等于已到场，堵车可能延迟。请查看状态、失败通知及剩余镇压时间。", "暴動後の復旧と経路\n\n暴動はデモより人数が多く速く移動し、行進沿いや現場付近の建物の火災・倒壊、道路破損を起こします。警察が到着して現場を維持する間は行進と追加被害を止めます。\n\n鎮圧成功は群衆の解散であり自動復旧ではありません。消火・再建・道路接続は別に確認してください。現版では全建物の再建を警察成功の条件にしていません。\n\n行進には歩道付きの地上一般道路が必要です。見つからない場合は庁舎の入口と接続を確認。橋・高架・トンネル・高速・歩行者区域だけでは経路にならない場合があります。\n\n警察車両と現場は別々に表示できます。要請と到着は別で、渋滞で遅れる場合があります。状態・失敗案内・残り時間を確認してください。", "Tras los disturbios: daños y rutas\n\nLa multitud es mayor y más rápida que en una protesta. Puede incendiar o derrumbar edificios y dañar vías durante la marcha. La llegada de policía que mantenga el lugar pausa la marcha y nuevos daños.\n\nEl éxito dispersa a la multitud, pero no repara nada. Revise extinción, reconstrucción y conexiones. Esta versión no exige reconstruir todos los edificios para que la intervención tenga éxito.\n\nLa marcha requiere calles normales a nivel del suelo con aceras. Si no hay ruta, compruebe el acceso a la sede. Puentes, elevados, túneles, autopistas o zonas peatonales por sí solos pueden no servir.\n\nVer policía y Ver lugar muestran posiciones distintas. Solicitar no significa llegar; los atascos pueden retrasar el despliegue. Revise estado, fallos y tiempo restante." });
            d.Add("폭동 전환", new string[] { "Escalated to riot", "转为暴乱", "暴動に移行", "Escalada a disturbios" });
            d.Add("폭동 진행 중", new string[] { "Riot in progress", "暴乱进行中", "暴動進行中", "Disturbios en curso" });
            d.Add("폭동 해산: 경찰 도착 후 진압을 마쳤습니다.", new string[] { "Riot ended after a successful police intervention.", "警察成功镇压，暴乱已解散。", "警察の鎮圧が完了し、暴動は解散しました。", "Los disturbios terminaron tras la intervención policial." });
            d.Add("폭동 현장에 투입된 경찰이 진압에 실패해 철수했습니다. 추가 경찰력 투입을 검토 중이며, 현장 접근을 삼가시기 바랍니다. #진압실패 #현장통제", new string[] { "Police at the riot scene failed to restore order and withdrew. Further deployment is under consideration. Avoid the area. #InterventionFailed #RoadClosure", "现场警察镇压失败后撤离，正在考虑增派警力。请勿接近现场。#镇压失败 #现场管制", "現場の警察は鎮圧に失敗し撤退しました。追加出動を検討中です。現場を避けてください。#鎮圧失敗 #現場規制", "La policía no logró restablecer el orden y se retiró. Se estudian refuerzos. Eviten la zona. #IntervenciónFallida #CorteVial" });
            d.Add("폭동·경찰 · 난이도와 점검\n\n행복도 20점 미만에서는 시위가 폭동으로 전환될 수 있습니다.\n폭동은 더 빠르게 이동하며 주변 건물과 도로에 피해를 줍니다.\n시위·폭동 현장과 진압 차량 주변에서는 일반 차량이 우회합니다.\n대체 경로가 없으면 정체나 경로 실패가 생길 수 있습니다.\n\n경찰 출동 요청 시 2~3대 배치를 시도합니다.\n‘경찰차 보기’로 실제 배치 차량을 확인하세요.\n현장 도착 후 30게임 분 뒤 진압을 판정하며,\n15% 확률로 실패하면 다시 출동 요청이 필요합니다.\n차량이 오지 않으면 출동 가능한 경찰서와 연결도로를 확인하세요.\n\n모드 옵션의 난이도는 1이 여유롭고 5가 가장 엄격합니다.\n행복도 감점 배율: 0.45 / 0.7 / 1 / 1.2 / 1.45\n일반 민원 기본 대응 시간: 48 / 36 / 24 / 15 / 9게임 시간\n필수시설 접수 대기: 3 / 2 / 1 / 0.5 / 0게임 시간\n5단계의 즉시 접수도 첫 완료 집계에서 피해가 확인되어야 합니다.\n\n결과가 이상하면 조회 지역·집계 완료·관할·통계 기준을 확인하세요.\n업데이트 시험 전에는 별도 도시 저장본을 남기는 것을 권장합니다.", new string[] { "Riots, police and difficulty\n\nBelow 20 happiness a protest can escalate into a riot. Riots move faster and damage buildings and roads. Ordinary traffic diverts around crowds and deployed police. Without another route, queues or pathfinding failures can occur.\n\nA police request attempts to deploy 2–3 vehicles. View police follows an assigned vehicle. Intervention is decided 30 game minutes after arrival, with a 15% failure chance requiring a new request. If none arrive, check available police stations and road access.\n\nDifficulty 1 is relaxed and 5 is harsh.\nHappiness penalty multipliers: 0.45 / 0.7 / 1 / 1.2 / 1.45.\nNormal response periods: 48 / 36 / 24 / 15 / 9 game hours.\nEssential intake waits: 3 / 2 / 1 / 0.5 / 0 game hours. Even level 5 waits for the first completed census to identify impact.\n\nIf results seem wrong, verify scope, census completion, jurisdiction and statistical thresholds. Keep a separate save before testing updates.", "暴乱、警察与难度\n\n幸福度低于20时示威可转为暴乱，速度更快且损毁建筑和道路。普通车辆绕开群众及镇压警车，无替代路线可能堵塞或寻路失败。\n\n每次请求尝试派出2～3辆警车，查看警车可跟随已分配车辆。到场30游戏分钟后判定，15%概率失败需再次请求。未到场时检查可用警局和道路。\n\n难度1宽松、5严格。\n幸福度扣分倍数：0.45 / 0.7 / 1 / 1.2 / 1.45。\n一般应对期：48 / 36 / 24 / 15 / 9游戏小时。\n必需设施受理等待：3 / 2 / 1 / 0.5 / 0游戏小时。第5档也需首次完整统计确认影响。\n\n结果异常时检查范围、统计完成状态、辖区和阈值。测试更新前请另存城市。", "暴動・警察・難易度\n\n幸福度20未満でデモが暴動に移行する場合があります。より速く移動して建物・道路に被害を与えます。一般車両は群衆や鎮圧車両を迂回し、代替経路がなければ渋滞や経路失敗が起こり得ます。\n\n警察要請は2～3台の配備を試みます。警察車両を見ると配備車を追えます。到着30ゲーム分後に判定し、15%で失敗すると再要請が必要です。来ない場合は警察署と道路接続を確認してください。\n\n難易度1は余裕があり、5が最も厳格です。\n減点倍率：0.45 / 0.7 / 1 / 1.2 / 1.45。\n一般対応期間：48 / 36 / 24 / 15 / 9ゲーム時間。\n必須設備の受付待ち：3 / 2 / 1 / 0.5 / 0ゲーム時間。5でも最初の完了集計による被害確認が必要です。\n\n表示範囲・集計・管轄・基準を確認し、更新試験前に別途保存してください。", "Disturbios, policía y dificultad\n\nPor debajo de 20 de felicidad, una protesta puede escalar. Los disturbios avanzan más rápido y dañan edificios y vías. El tráfico normal evita multitudes y policía; sin alternativa puede atascarse o fallar la ruta.\n\nUna solicitud intenta enviar 2–3 vehículos. Ver policía sigue uno asignado. Se decide la intervención 30 minutos de juego tras llegar, con un 15% de fracaso que exige otra solicitud. Si no llegan, revise comisarías disponibles y accesos.\n\nLa dificultad 1 es relajada y la 5 exigente.\nMultiplicadores: 0,45 / 0,7 / 1 / 1,2 / 1,45.\nPlazos normales: 48 / 36 / 24 / 15 / 9 horas de juego.\nEsenciales: espera de 3 / 2 / 1 / 0,5 / 0 horas. Incluso el nivel 5 necesita un recuento completo.\n\nAnte resultados extraños, revise ámbito, recuento, jurisdicción y umbrales. Conserve un guardado aparte antes de probar actualizaciones." });
            d.Add("폭동", new string[] { "Riot", "暴乱", "暴動", "Disturbios" });
            d.Add("폭동으로 전환", new string[] { "Escalate to riot", "转为暴乱", "暴動に移行", "Escalar a disturbios" });
            d.Add("폭동은 요구 개선과 별도로 경찰 진압 성공이 필요합니다.", new string[] { "Riots require successful police intervention, even if demands improve.", "即使诉求得到改善，暴乱仍需警察成功镇压。", "要求が改善されても、暴動の解散には警察の鎮圧成功が必要です。", "Los disturbios requieren una intervención policial exitosa aunque mejoren las demandas." });
            d.Add("피해 비율", new string[] { "Affected share", "受影响比例", "被害割合", "Proporción afectada" });
            d.Add("해결", new string[] { "Resolved", "已解决", "解決", "Resuelto" });
            d.Add("해산 조건", new string[] { "Dispersal conditions", "解散条件", "解散条件", "Condiciones de dispersión" });
            d.Add("행복도 · 5단계와 감점\n\n행복도는 0~100점이며 단계는 다음과 같습니다.\n0~20 미만: 최악 / 20~40 미만: 나쁨\n40~60 미만: 보통 / 60~80 미만: 좋음 / 80~100: 만족\n\n도시 점수는 집계 가능한 일반 지구 점수의 산술평균입니다.\n인구가 많은 구에 더 큰 비중을 두는 평균은 아닙니다.\n해당 지구가 없으면 전체 시민 집계를 사용합니다.\n\n피해가 넓게 퍼질수록 감점이 커집니다. 심각 피해는 1.5배로\n반영하며, 같은 시민의 같은 사유는 중복해서 세지 않습니다.\n소수의 잔여 피해는 고정 감점을 비율에 따라 줄입니다.\n버려진 건물은 별도 감점이 있으므로 복구도 확인하세요.\n\n게임의 평균 건강은 시민의 건강 상태를, 이 모드의 행복도는\n주거·교통·치안 등 여러 생활 여건을 함께 나타냅니다.\n‘추이 보기’에서는 최근 24게임 시간의 변화를 확인합니다.\n난이도를 바꾸거나 인구와 지구 경계가 달라지면 행복도에도 반영됩니다.", new string[] { "Happiness: levels and penalties\n\nScores range from 0 to 100:\n0–under 20: Worst; 20–under 40: Poor;\n40–under 60: Normal; 60–under 80: Good; 80–100: Satisfied.\n\nThe city score is the arithmetic mean of eligible regular districts, not a population-weighted average. Without eligible districts it uses all residents.\n\nWider impact means larger penalties. Severe cases count 1.5 times; the same resident is not counted twice for one reason. Fixed penalties taper for small remaining impacts. Abandoned buildings have separate penalties and need attention.\n\nThe game's average health measures health; this mod's happiness covers housing, traffic, safety and other living conditions. View trend shows the last 24 game hours. Difficulty, population and district boundary changes can alter the score.", "幸福度等级与扣分\n\n分数范围0～100：\n0至不足20极差，20至不足40较差，40至不足60一般，60至不足80良好，80～100满意。\n\n城市分数为可统计普通分区的算术平均，不按人口加权。没有合格分区时使用全体市民统计。\n\n影响越广扣分越大，严重按1.5倍计算，同一市民同一原因不重复计数。少量残余影响会按比例降低固定扣分，废弃建筑另有扣分。\n\n游戏平均健康衡量健康，本模组幸福度综合住房、交通、安全等生活条件。趋势显示最近24游戏小时；难度、人口及边界变化也影响分数。", "幸福度の段階と減点\n\n0～100点で、0～20未満：最悪、20～40未満：悪い、40～60未満：普通、60～80未満：良い、80～100：満足です。\n\n都市点は集計可能な通常地区の算術平均で、人口による加重平均ではありません。該当地区がなければ全市民を使います。\n\n被害が広いほど減点が増え、深刻な被害は1.5倍です。同じ市民・原因を重複計上しません。少数の残存被害は固定減点を割合で減らします。廃墟は別途減点されます。\n\nゲームの平均健康は健康状態、この幸福度は住居・交通・安全などの生活条件を表します。推移を見ると直近24ゲーム時間を確認でき、難易度・人口・地区境界の変更も点数に反映されます。", "Felicidad: niveles y penalizaciones\n\nLa escala va de 0 a 100:\n0–menos de 20: Pésima; 20–menos de 40: Mala;\n40–menos de 60: Normal; 60–menos de 80: Buena; 80–100: Satisfecha.\n\nLa ciudad usa la media aritmética de los distritos válidos, no ponderada por población. Sin distritos válidos, utiliza todos los residentes.\n\nCuanto más extendido el impacto, mayor descuento. Los casos graves cuentan 1,5 veces; no se duplica un ciudadano por la misma causa. Los pequeños impactos residuales reducen proporcionalmente la penalización fija. El abandono se descuenta aparte.\n\nLa salud media del juego mide salud; esta felicidad reúne vivienda, tráfico, seguridad y otras condiciones. La tendencia cubre 24 horas de juego. Dificultad, población y límites de distrito pueden cambiar la puntuación." });
            d.Add("행복도 관리", new string[] { "Happiness management", "幸福度管理", "幸福度管理", "Gestión de felicidad" });
            d.Add("행복도 모듈 오류로 작업을 중단했습니다. output_log.txt를 확인하세요.", new string[] { "Happiness module stopped due to an error. Check output_log.txt.", "幸福度模块因错误停止，请检查 output_log.txt。", "幸福度機能がエラーで停止しました。output_log.txt を確認してください。", "El módulo de felicidad se detuvo por un error. Revise output_log.txt." });
