            d.Add("현장 보기", new string[] { "View scene", "查看现场", "現場を見る", "Ver lugar" });
            d.Add("현장이 변경되었습니다. 다시 집계해 주세요.", new string[] { "The scene changed. Run the census again.", "现场已变化，请重新统计。", "現場が変わりました。再集計してください。", "El lugar cambió. Repita el recuento." });
