            d.Add("언어 변경은 게임을 다시 시작한 뒤 적용됩니다. 기존 기록과 도시·도로·건물 이름은 그대로 유지됩니다.", new string[] { "Restart the game to apply the language. Existing records and city, road and building names are retained.", "语言将在重启游戏后生效，既有记录和城市、道路、建筑名称保持不变。", "言語の変更はゲーム再起動後に適用されます。既存の記録や都市・道路・建物名は維持されます。", "Reinicie el juego para aplicar el idioma. Se conservan los registros existentes y nombres de ciudades, vías y edificios." });
            d.Add("언어 설정을 저장하지 못했습니다. 다시 시도해 주세요.", new string[] { "Could not save the language. Please try again.", "无法保存语言设置，请重试。", "言語設定を保存できませんでした。再試行してください。", "No se pudo guardar el idioma. Inténtelo de nuevo." });
            d.Add("번역 추가: 아래 폴더에 언어 파일(.json)을 넣고 게임을 다시 시작하세요. 만드는 방법은 같은 폴더의 README.txt에 있습니다.", new string[] { "Add a translation: put a language file (.json) in the folder below and restart the game. See README.txt in the same folder for how to make one.", "添加翻译：将语言文件（.json）放入下方文件夹并重新启动游戏。制作方法请参阅同一文件夹中的 README.txt。", "翻訳の追加：下のフォルダーに言語ファイル（.json）を入れてゲームを再起動してください。作り方は同じフォルダーの README.txt にあります。", "Añadir una traducción: coloca un archivo de idioma (.json) en la carpeta de abajo y reinicia el juego. Consulta README.txt en la misma carpeta para crearlo." });
            d.Add("이벤트 켜기·끄기", new string[] { "Optional events", "可选事件", "イベントのオン・オフ", "Eventos opcionales" });
            d.Add("황당 민원 (엉뚱한 요청)", new string[] { "Odd requests (silly complaints)", "奇葩民诉（荒唐请求）", "おかしな民願（突飛な要望）", "Peticiones absurdas" });
            d.Add("행정청 소란 (방문 민원인 난동과 경찰 출동)", new string[] { "Office disturbances (unruly visitors and police response)", "行政机关闹事（来访民诉人闹事与警察出动）", "行政庁での騒ぎ（来庁者の騒ぎと警察出動）", "Altercados en oficinas (visitantes conflictivos y policía)" });
            d.Add("잘하면 보상이 있습니다. 구청 신뢰가 높으면 시위가 줄고 민원 대응 기한과 행복도에 여유가 생깁니다. 주민 건의를 들어주면 신뢰가 오르고, 게임 7일마다 행정 평가 등급(S~D)을 받습니다.", new string[] { "Good administration now pays off. High district office trust means fewer protests, more response time and a small happiness bonus. Delivering residents' suggestions raises trust, and every 7 game days you receive an administration grade (S to D).", "良好的行政现在会得到回报。区政府信任高时抗议减少，民诉处理期限和幸福度更有余裕。落实居民建议可提高信任，每7个游戏日还会获得行政评价等级（S~D）。", "良い行政には見返りがあります。区役所の信頼が高いとデモが減り、陳情の対応期限と幸福度に余裕が生まれます。住民要望に応えると信頼が上がり、ゲーム内7日ごとに行政評価ランク（S～D）を受け取ります。", "Ahora una buena administración tiene recompensa. Con mucha confianza en la oficina de distrito hay menos protestas, más plazo para las quejas y un pequeño extra de felicidad. Cumplir sugerencias vecinales sube la confianza y cada 7 días de juego recibes una nota de administración (S a D)." });
            d.Add("옵션에서 황당 민원, 행정청 소란, 시설 반대, 주민 건의를 각각 켜거나 끌 수 있습니다.", new string[] { "Odd requests, office disturbances, facility opposition and residents' suggestions can each be switched on or off in the options.", "可在选项中分别开启或关闭奇葩民诉、行政机关闹事、设施反对和居民建议。", "オプションでおかしな民願、行政庁での騒ぎ、施設反対、住民要望をそれぞれオン・オフできます。", "Las peticiones absurdas, los altercados en oficinas, la oposición a instalaciones y las sugerencias vecinales se pueden activar o desactivar por separado en las opciones." });
            d.Add("강행", new string[] { "Proceed anyway", "强行推进", "強行", "Seguir adelante" });
            d.Add("건의 답변 기한까지  ", new string[] { "Time to answer the suggestion  ", "建议答复期限  ", "要望の回答期限まで  ", "Plazo para responder  " });
            d.Add("건의 이행 기한까지  ", new string[] { "Time to deliver the suggestion  ", "建议落实期限  ", "要望の実行期限まで  ", "Plazo para cumplir  " });
            d.Add("기한 안에 서비스를 개선하면 구청 신뢰가 오릅니다.", new string[] { "Improve the service before the deadline to raise district office trust.", "在期限内改善服务可提高区政府信任。", "期限内にサービスを改善すると区役所の信頼が上がります。", "Mejora el servicio antes del plazo para aumentar la confianza en la oficina de distrito." });
            d.Add("보류", new string[] { "Set aside", "暂缓", "保留", "Aplazar" });
            d.Add("보상 없이 시설 운영을 계속합니다. 난이도에 따라 신뢰 하락과 행복도 감점, 집회 또는 폭동 예고가 따릅니다.", new string[] { "Keep the facility without compensation. Depending on difficulty this lowers trust and happiness, or announces a protest or riot.", "不给补偿继续运营设施。根据难度，会降低信任和幸福度，或预告集会、暴动。", "補償せずに施設の運営を続けます。難易度に応じて信頼と幸福度の低下、集会または暴動の予告が起こります。", "Mantén la instalación sin compensar. Según la dificultad baja la confianza y la felicidad, o se anuncia una protesta o disturbio." });
            d.Add("불이익 없이 건의를 닫습니다.", new string[] { "Close the suggestion with no penalty.", "关闭建议，没有任何不利影响。", "不利益なく要望を閉じます。", "Cierra la sugerencia sin penalización." });
            d.Add("설명회·보상", new string[] { "Briefing & compensation", "说明会·补偿", "説明会・補償", "Reunión y compensación" });
            d.Add("수락 · 추진 약속", new string[] { "Accept · promise action", "接受 · 承诺推进", "受諾・実施を約束", "Aceptar · prometer" });
            d.Add("주민 반대 응답 기한까지  ", new string[] { "Time to respond to residents  ", "回应居民反对的期限  ", "住民の反対への回答期限まで  ", "Plazo para responder a los vecinos  " });
            d.Add("집회 예고까지  ", new string[] { "Announced rally in  ", "预告集会倒计时  ", "予告された集会まで  ", "Protesta anunciada en  " });
            d.Add("표시된 비용을 지출해 주민 반대를 해소합니다. 예고된 집회도 취소됩니다.", new string[] { "Spend the listed amount to settle the opposition. Any announced rally is cancelled.", "支出所示费用以化解居民反对，已预告的集会也会取消。", "表示された費用を支出して住民の反対を解消します。予告された集会も取り消されます。", "Paga el importe indicado para resolver la oposición. También se cancela la protesta anunciada." });
            d.Add(" · 시설 반대: ", new string[] { " · Facility opposition: ", " · 设施反对：", " · 施設反対：", " · Oposición a instalación: " });
            d.Add(" · 시설 철거로 주민 반대가 해소되었습니다. #시설반대", new string[] { " · The facility was removed and the residents' opposition is settled. #NIMBY", " · 设施已拆除，居民反对随之化解。#设施反对", " · 施設の撤去により住民の反対が解消されました。#施設反対", " · La instalación fue retirada y la oposición vecinal se resolvió. #Oposición" });
            d.Add(" · 약속한 주민 건의의 이행 기한이 지났습니다. #주민건의", new string[] { " · The deadline for a promised residents' suggestion has passed. #Suggestion", " · 已承诺的居民建议落实期限已过。#居民建议", " · 約束した住民要望の実行期限が過ぎました。#住民要望", " · Venció el plazo de una sugerencia vecinal prometida. #Sugerencia" });
            d.Add(" · 예산이 부족해 주민 보상을 집행하지 못했습니다. #시설반대", new string[] { " · Compensation could not be paid due to insufficient funds. #NIMBY", " · 因预算不足，未能向居民支付补偿。#设施反对", " · 予算不足のため住民への補償を執行できませんでした。#施設反対", " · No se pudo pagar la compensación por falta de fondos. #Oposición" });
            d.Add(" · 인근 주민들이 시설 설치에 반대 의견을 제출했습니다. 행정청이 주민 설명회와 보상 여부를 검토합니다. #시설반대", new string[] { " · Nearby residents have filed opposition to the facility. The office is reviewing a briefing and compensation. #NIMBY", " · 附近居民提交了反对设置该设施的意见。行政机关正在研究说明会与补偿事宜。#设施反对", " · 近隣住民が施設の設置に反対意見を提出しました。行政庁が住民説明会と補償を検討します。#施設反対", " · Los vecinos cercanos se oponen a la instalación. La oficina estudia una reunión informativa y una compensación. #Oposición" });
            d.Add(" · 주민 건의: ", new string[] { " · Residents' suggestion: ", " · 居民建议：", " · 住民要望：", " · Sugerencia vecinal: " });
            d.Add(" · 주민 건의를 이행했습니다. 구청 신뢰가 올랐습니다. #주민건의", new string[] { " · A residents' suggestion was delivered. District office trust rose. #Suggestion", " · 已落实居民建议，区政府信任提高。#居民建议", " · 住民要望を実行しました。区役所の信頼が上がりました。#住民要望", " · Se cumplió una sugerencia vecinal. Subió la confianza en la oficina de distrito. #Sugerencia" });
            d.Add(" · 주민 반대에도 시설 운영을 계속하기로 해 격렬한 시위가 예고되었습니다. 설명회·보상이나 시설 철거로 막을 수 있습니다. #집회예고", new string[] { " · The facility stays despite opposition, and a violent protest has been announced. A briefing with compensation or removing the facility can prevent it. #RallyNotice", " · 不顾居民反对继续运营设施，激烈抗议已被预告。召开说明会并补偿或拆除设施可以阻止。#集会预告", " · 住民の反対にもかかわらず施設の運営を続けるため、激しいデモが予告されました。説明会・補償または施設の撤去で防げます。#集会予告", " · La instalación sigue pese a la oposición y se anuncia una protesta violenta. Una reunión con compensación o retirar la instalación puede evitarla. #Aviso" });
            d.Add(" · 주민 반대에도 시설 운영을 계속하기로 해 반대 집회가 예고되었습니다. 설명회·보상이나 시설 철거로 막을 수 있습니다. #집회예고", new string[] { " · The facility stays despite opposition, and a protest rally has been announced. A briefing with compensation or removing the facility can prevent it. #RallyNotice", " · 不顾居民反对继续运营设施，反对集会已被预告。召开说明会并补偿或拆除设施可以阻止。#集会预告", " · 住民の反対にもかかわらず施設の運営を続けるため、反対集会が予告されました。説明会・補償または施設の撤去で防げます。#集会予告", " · La instalación sigue pese a la oposición y se anuncia una protesta. Una reunión con compensación o retirar la instalación puede evitarla. #Aviso" });
            d.Add(" · 주민 반대에도 시설 운영을 계속합니다. 인근 지역의 불만이 한동안 이어질 것으로 보입니다. #시설반대", new string[] { " · The facility stays despite opposition. Discontent nearby is expected to last for a while. #NIMBY", " · 不顾居民反对继续运营设施。预计附近地区的不满会持续一段时间。#设施反对", " · 住民の反対にもかかわらず施設の運営を続けます。近隣の不満はしばらく続く見込みです。#施設反対", " · La instalación sigue pese a la oposición. Se espera que el malestar vecinal dure un tiempo. #Oposición" });
            d.Add(" · 주민 설명회를 열고 보상하기로 해 예고된 집회를 취소합니다. #시설반대", new string[] { " · A residents' briefing and compensation were agreed, so the announced rally is cancelled. #NIMBY", " · 决定召开居民说明会并给予补偿，预告的集会取消。#设施反对", " · 住民説明会を開き補償することになり、予告された集会を取り消します。#施設反対", " · Se acordó una reunión y una compensación, así que se cancela la protesta anunciada. #Oposición" });
            d.Add(" · 주민 설명회를 열고 인근 주민에게 보상하기로 했습니다. #시설반대", new string[] { " · A residents' briefing will be held and nearby residents compensated. #NIMBY", " · 决定召开居民说明会并向附近居民给予补偿。#设施反对", " · 住民説明会を開き、近隣住民に補償することになりました。#施設反対", " · Se celebrará una reunión informativa y se compensará a los vecinos cercanos. #Oposición" });
            d.Add(" · 주민들이 서비스 확충을 건의했습니다. 도시 행정 민원 목록에서 확인할 수 있습니다. #주민건의", new string[] { " · Residents have suggested expanding a service. See the complaint list in the administration panel. #Suggestion", " · 居民建议扩充服务，可在城市行政民诉列表中查看。#居民建议", " · 住民がサービスの拡充を要望しました。都市行政の民願一覧で確認できます。#住民要望", " · Los vecinos sugieren ampliar un servicio. Consúltalo en la lista de quejas de administración. #Sugerencia" });
            d.Add(" 구청 건의", new string[] { " district office suggestion", "区政府建议", " 区役所への要望", " · sugerencia a la oficina de distrito" });
            d.Add("% · 건의 당시 ", new string[] { "% · when suggested ", "% · 建议时 ", "% · 要望時 ", "% · al sugerirse " });
            d.Add("\n시설을 철거·이전해도 반대가 해소됩니다.", new string[] { "\nRemoving or relocating the facility also settles the opposition.", "\n拆除或迁移设施也能化解反对。", "\n施設を撤去・移転しても反対は解消されます。", "\nRetirar o trasladar la instalación también resuelve la oposición." });
            d.Add("격렬한 시위 예고", new string[] { "Violent protest announced", "激烈抗议预告", "激しいデモの予告", "Protesta violenta anunciada" });
            d.Add("교도소", new string[] { "Prison", "监狱", "刑務所", "Prisión" });
            d.Add("구청 신뢰 하락 · 7일간 지역 행복도 감점", new string[] { "Lower trust · district happiness penalty for 7 days", "区政府信任下降 · 7天内地区幸福度扣分", "区役所の信頼低下・7日間地区の幸福度減点", "Menos confianza · penalización de felicidad del distrito durante 7 días" });
            d.Add("구청 신뢰 하락 · 격렬한 시위(폭동) 예고", new string[] { "Lower trust · violent protest (riot) announced", "区政府信任下降 · 预告激烈抗议（暴动）", "区役所の信頼低下・激しいデモ（暴動）の予告", "Menos confianza · se anuncia una protesta violenta (disturbio)" });
            d.Add("구청 신뢰 하락 · 반대 집회 예고", new string[] { "Lower trust · protest rally announced", "区政府信任下降 · 预告反对集会", "区役所の信頼低下・反対集会の予告", "Menos confianza · se anuncia una protesta" });
            d.Add("민원 기준보다는 적지만 이 서비스가 부족하다는 주민 건의입니다. 수락하고 기한 안에 개선하면 신뢰가 오르고, 지키지 못하면 조금 떨어집니다. 보류하면 영향이 없습니다.", new string[] { "Fewer residents are affected than a complaint needs, but they suggest improving this service. Accept and improve it in time to raise trust; a broken promise lowers it slightly. Setting it aside has no effect.", "虽未达到民诉标准，但居民建议改善这项服务。接受并在期限内改善可提高信任，未能兑现会略微下降。暂缓则没有影响。", "陳情の基準には届きませんが、このサービスが足りないという住民要望です。受諾して期限内に改善すると信頼が上がり、守れないと少し下がります。保留しても影響はありません。", "Hay menos afectados de los necesarios para una queja, pero los vecinos sugieren mejorar este servicio. Acepta y mejóralo a tiempo para ganar confianza; incumplir la reduce un poco. Aplazar no tiene efecto." });
            d.Add("반대 집회 예고", new string[] { "Protest rally announced", "反对集会预告", "反対集会の予告", "Protesta anunciada" });
            d.Add("발전소", new string[] { "Power plant", "发电厂", "発電所", "Central eléctrica" });
            d.Add("버스 차고지", new string[] { "Bus depot", "公交车场", "バス車庫", "Cocheras de autobuses" });
            d.Add("시설 반대: ", new string[] { "Facility opposition: ", "设施反对：", "施設反対：", "Oposición a instalación: " });
            d.Add("시설 보기", new string[] { "View facility", "查看设施", "施設を見る", "Ver instalación" });
            d.Add("쓰레기 시설", new string[] { "Garbage facility", "垃圾设施", "ごみ処理施設", "Instalación de residuos" });
            d.Add("예고 시간이 되면 행진이 시작됩니다. 설명회·보상이나 시설 철거로 취소할 수 있습니다.", new string[] { "The march starts when the notice runs out. A briefing with compensation or removing the facility cancels it.", "预告时间一到游行就会开始。召开说明会并补偿或拆除设施可以取消。", "予告時間になると行進が始まります。説明会・補償または施設の撤去で取り消せます。", "La marcha empieza cuando vence el aviso. Una reunión con compensación o retirar la instalación la cancela." });
            d.Add("응답하지 않거나 강행하면: ", new string[] { "If ignored or overruled: ", "若不回应或强行推进：", "回答しないか強行すると：", "Si no respondes o sigues adelante: " });
            d.Add("지난 7일 행정 평가는 ", new string[] { "Administration review for the past 7 days: grade ", "过去7天行政评价为 ", "過去7日の行政評価は ", "Evaluación de los últimos 7 días: nota " });
